#!/usr/bin/env python3
"""Generate a link-only stub shared library source from an AOSP .map.txt.

Vendor code must link against LL-NDK libraries such as libbinder_ndk, but the
public NDK stubs omit platform-only symbols (AServiceManager_addService, ...).
This emits <out>.c with an empty function per symbol and <out>.ver, a version
script with the same version nodes, so the binary binds to the real library on
the device at runtime. extern "C++" blocks are skipped.

usage: gen-stub.py MAP_TXT OUT_PREFIX
"""

import re
import sys

src, out = sys.argv[1], sys.argv[2]
nodes = []  # (name, [symbols])
cur = None
in_cxx = False
for raw in open(src):
  line = raw.split("#", 1)[0].strip()
  if not line:
    continue
  m = re.match(r"^(\w+)\s*\{$", line)
  if m:
    cur = (m.group(1), [])
    nodes.append(cur)
    continue
  if line.startswith('extern "C++"'):
    in_cxx = True
    continue
  if line.startswith("}"):
    if in_cxx:
      in_cxx = False
    else:
      cur = None
    continue
  if cur is None or in_cxx or line.endswith(":"):
    continue
  sym = line.rstrip(";").strip()
  if sym and sym != "*" and re.match(r"^\w+$", sym):
    cur[1].append(sym)

with open(out + ".c", "w") as f:
  f.write(
    "/* generated by gen-stub.py from %s; link-only stub */\n"
    % src.split("/")[-1]
  )
  for _, syms in nodes:
    for s in syms:
      f.write("void %s(void) {}\n" % s)
with open(out + ".ver", "w") as f:
  for name, syms in nodes:
    f.write("%s {\n  global:\n" % name)
    for s in syms:
      f.write("    %s;\n" % s)
    f.write("};\n")
  f.write("LOCAL_STUB { local: *; };\n")
print(sum(len(s) for _, s in nodes), "symbols")
